class_name ActorData
extends Resource
@export var id: String = ""
@export var type_id: StringName = &"audio"
@export var display_name: String = ""
@export var values: Dictionary = {}
@export var animation_tracks: Array[Resource] = []
static func new_id() -> String:
 return Crypto.new().generate_random_bytes(16).hex_encode()
func get_value(key: StringName, fallback: Variant = null) -> Variant:
 return values.get(key, fallback)

class_name ActorProperty
extends Resource
var options:Dictionary={}

extends SceneTree
# Runtime-only fixture bootstrap. Writes a class-name index in this copied test
# directory; does not start an editor, load production scenes, or alter sources.
func _initialize()->void:
 var classes:Array[Dictionary]=[]
 var pending:Array[String]=["res://Workspaces/AudioWorkspace","res://scripts/actors/core","res://stubs"]
 var class_pattern:=RegEx.new();class_pattern.compile("(?m)^class_name\\s+([A-Za-z_][A-Za-z0-9_]*)")
 var base_pattern:=RegEx.new();base_pattern.compile("(?m)^extends\\s+([A-Za-z_][A-Za-z0-9_]*)")
 for directory in pending:
  for name in DirAccess.get_files_at(directory):
   if not name.ends_with(".gd"):continue
   var path:=directory.path_join(name);var source:=FileAccess.get_file_as_string(path)
   var class_match:=class_pattern.search(source);var base_match:=base_pattern.search(source)
   if class_match==null:continue
   if base_match==null:push_error("Missing explicit native base in "+path);quit(1);return
   classes.append({"base":StringName(base_match.get_string(1)),"class":StringName(class_match.get_string(1)),"icon":"","is_abstract":false,"is_tool":false,"language":&"GDScript","path":path})
 classes.sort_custom(func(a:Dictionary,b:Dictionary):return str(a["class"])<str(b["class"]))
 DirAccess.make_dir_recursive_absolute("res://.godot")
 var index:=FileAccess.open("res://.godot/global_script_class_cache.cfg",FileAccess.WRITE)
 if index==null:push_error("Could not write fixture class index");quit(1);return
 index.store_string("list="+var_to_str(classes)+"\n");index.close()
 print("FIXTURE_BOOTSTRAP ",classes.size()," source-derived classes; Godot ",Engine.get_version_info().string)
 quit(0)
